// Verus program: compute the maximum value reached by a running counter
// while scanning a string of 'I'/'D' operations.

use vstd::prelude::*;

verus! {

fn solve(n: i8, s: Vec<char>) -> (res: i8)
    requires
        1 <= n <= 100,
        s.len() == n as usize,
        forall|i: int| 0 <= i < s.len() ==> (s[i] == 'I' || s[i] == 'D'),
    ensures
        // Result is the maximum counter value seen, including the initial 0.
        res as int == max_counter(s@),
        // Problem statement guarantees non-negative answer; we prove it.
        0 <= res,
{
    let mut cur: i8 = 0;
    let mut best: i8 = 0;
    let mut i: usize = 0;

    while i < s.len()
        invariant
            0 <= i <= s.len(),
            // cur is the counter value after processing the first i chars
            cur as int == counter_after(s@, i as int),
            // best is the maximum seen among prefixes up to i (including empty prefix)
            best as int == max_counter_prefix(s@, i as int),
            0 <= best,
        decreases s.len() - i
    {
        if s[i] == 'I' {
            cur = cur + 1;
        } else {
            // By the precondition, any non-'I' must be 'D'
            assert(s[i] == 'D');
            cur = cur - 1;
        }

        if cur > best {
            best = cur;
        }

        i = i + 1;
    }

    proof {
        // After the loop, i == s.len(), so best is the maximum over all prefixes.
        assert(i == s.len());
        assert(best as int == max_counter(s@));
        assert(0 <= best);
    }

    best
}

/* ===================== Specifications (pure) ===================== */

// Counter value after processing the first `k` characters (k in [0..len]).
spec fn counter_after(s: Seq<char>, k: int) -> int
    decreases k
{
    if k <= 0 {
        0
    } else {
        counter_after(s, k - 1)
            + if s[k - 1] == 'I' { 1 } else { -1 }
    }
}

// Maximum counter value among prefixes of length 0..k (inclusive of 0).
spec fn max_counter_prefix(s: Seq<char>, k: int) -> int
    decreases k
{
    if k <= 0 {
        0
    } else {
        let prev = max_counter_prefix(s, k - 1);
        let cur  = counter_after(s, k);
        if prev >= cur { prev } else { cur }
    }
}

// Maximum counter value over the entire scan (prefixes 0..len).
spec fn max_counter(s: Seq<char>) -> int {
    max_counter_prefix(s, s.len() as int)
}

} // verus!